//*****************************************************************************
//
// buzzer.h - Tone on the buzzer (PG1), generated by the Timer0 interrupt
//
//*****************************************************************************
#ifndef BUZZER_H
#define BUZZER_H

#include <stdint.h>

void buzzer_init(uint32_t sysClock);   // PG1 as output, Timer0 prepared
void buzzer_start(uint32_t freq);      // play a tone with freq Hz
void buzzer_stop(void);                // silence
void Timer0AIntHandler(void);          // ISR, entered in tm4c129encpdt_startup_ccs.c

#endif
